  mktPhaseAny: { en: "Any phase", es: "Cualquier fase", ru: "Любая фаза", fr: "Toutes les phases", de: "Jede Phase", pt: "Qualquer fase", it: "Qualsiasi fase", ja: "すべてのフェーズ", zh: "任意阶段", ht: "Nenpòt faz", ko: "전체 단계", tr: "Herhangi bir aşama", uk: "Будь-яка фаза", hi: "कोई भी चरण", ar: "أي مرحلة", vi: "Mọi giai đoạn", id: "Semua fase", pl: "Dowolna faza", th: "ทุกระยะ" },
  mktPhase1: { en: "Phase 1", es: "Fase 1", ru: "Фаза 1", fr: "Phase 1", de: "Phase 1", pt: "Fase 1", it: "Fase 1", ja: "フェーズ1", zh: "第 1 阶段", ht: "Faz 1", ko: "1단계", tr: "1. Aşama", uk: "Фаза 1", hi: "चरण 1", ar: "المرحلة 1", vi: "Giai đoạn 1", id: "Fase 1", pl: "Faza 1", th: "ระยะที่ 1" },
