  mktGpaPhase: { en: "GPA phase", es: "Fase GPA", ru: "Фаза GPA", fr: "Phase GPA", de: "GPA-Phase", pt: "Fase GPA", it: "Fase GPA", ja: "GPAフェーズ", zh: "GPA 阶段", ht: "Faz GPA", ko: "GPA 단계", tr: "GPA aşaması", uk: "Фаза GPA", hi: "GPA चरण", ar: "مرحلة GPA", vi: "Giai đoạn GPA", id: "Fase GPA", pl: "Faza GPA", th: "ระยะ GPA" },
